import { page, escape } from '../view'
import { ownerLeft, usDate, when } from '../format'
import { slab, stateChip } from '../ui'
import { facts, options, personOptions, table } from '../program/view'
import type { Person } from '../program/people'
import { usRegion } from '../program/boundary'
import { criticalities, dataTypes, kindLabels, tiers, type DocumentRow, type Profile } from './storage'
import { requestState, standing, type ApprovalRow, type LinkRow, type Need, type RequestRow } from './diligence'
import type { Template } from './caiq'
export interface VendorRow { id: string; name: string; criticality: string; data_access: string; review_due: string | null; owner_name: string | null; owner_left_at: string | null; risk_tier: string | null; approval: string; reassessment: string; missing: number }
const onboarding = (people: Person[]) => `<form method="post" action="/app/vendors" class="stack"><h3>Onboard a supplier</h3>
 <label>Vendor name<input name="name" required maxlength="200"></label><label>What the supplier provides<input name="service" maxlength="500" placeholder="Payroll SaaS"></label>
 <label>Website<input name="website" type="url" maxlength="300" placeholder="https://"></label><label>Criticality<select name="criticality" aria-label="Criticality">${options([...criticalities], 'medium')}</select></label>
 <fieldset><legend>Data the supplier can access</legend>${dataTypes.map(t => `<label><input type="checkbox" name="data_types" value="${escape(t)}"> ${escape(t)}</label>`).join(' ')}</fieldset>
 <label>Data access notes<input name="data_access" maxlength="500"></label><label>Hosting region<input name="region" maxlength="100" value="US"></label>
 <label>Risk tier (blank takes the suggestion)<select name="risk_tier" aria-label="Risk tier"><option value="">Suggest from criticality and data</option>${options([...tiers])}</select></label>
 <label>Annual cost (USD)<input name="annual_cost_usd" inputmode="numeric" maxlength="12"></label><label>Contract renewal date<input type="date" name="renewal_date"></label>
 <label>Supplier contact name<input name="contact_name" maxlength="200"></label><label>Supplier contact email<input type="email" name="contact_email" maxlength="254"></label>
 <label>Business owner<select name="owner_person_id" aria-label="Business owner">${personOptions(people, '', 'No owner yet')}</select></label><label>Review due<input type="date" name="review_due"></label>
 <button class="button-secondary">Add vendor</button></form>`
export async function vendorsPage(vendors: VendorRow[], people: Person[], tpl: Template[], owner: string) {
 const list = table(['Vendor', 'Tier', 'Criticality', 'Approval', 'Reassessment', 'Diligence gaps', 'Owner', 'Review due'], vendors.map(v => [`<a href="/app/vendors/${v.id}">${escape(v.name)}</a>`, escape(v.risk_tier ?? '—'), escape(v.criticality), escape(v.approval), escape(v.reassessment), String(v.missing), escape((v.owner_name ?? '—') + ownerLeft(v.owner_left_at)), escape(v.review_due ?? '—')]), 'Vendors')
 const templates = `<p class="panel-intro">Questionnaires: ${tpl.map(t => `${escape(t.name)} (${t.questions.length} questions${t.owner_built ? ', owner-built' : ', shipped'})`).join('; ')}. SIG Lite and SIG Core are licensed by Shared Assessments and are not shipped: import your licensed copy below.</p>`
 const builder = `<form method="post" action="/app/vendor-templates" class="stack"><h3>Owner-built questionnaire</h3><label>Template name<input name="name" required maxlength="200"></label><label>Questions, one per line (optional "ID: question")<textarea name="questions" rows="5" required></textarea></label><label><input type="checkbox" name="licensed_copy" value="yes"> I hold a licence for any licensed content in this template (required for SIG)</label><button class="button-secondary">Save template</button></form>`
 return page('Vendors', `${slab(`<section aria-labelledby="vendors-title"><h2 id="vendors-title">Vendors</h2><p class="panel-intro">Each supplier's data access, diligence, findings and approval. Evidence records your decisions and the supplier's statements; it does not certify a supplier, and every agreement or report shown is not verified by Evidence until you review it.</p>${list}</section>`)}<div class="app-columns">${slab(onboarding(people))}${slab(`<section aria-labelledby="templates-title"><h2 id="templates-title">Questionnaire templates</h2>${templates}${builder}</section>`)}</div>`, 200, { owner, active: 'vendors' })
}
export interface Detail {
 vendor: { id: string; name: string; criticality: string; data_access: string; review_due: string | null; owner_person_id: string | null }; owner_name: string | null; owner_left_at: string | null
 profile: Profile | null; subprocessors: Record<string, string | null>[]; documents: DocumentRow[]; requests: RequestRow[]; links: (LinkRow & { requests: number })[]; events: { link_id: string | null; action: string; outcome: string; at: string }[]
 findings: Record<string, string | null>[]; approvals: ApprovalRow[]; assertions: Record<string, string | null>[]; needs: Need[]; answers: Record<string, { question_id: string; answer: string; comment: string; answered_at: string }[]>
 reminders: { kind: string; cycle_key: string; recipient: string; state: string; created_at: string }[]; templates: Template[]
}
const chip = (s: string) => stateChip(s === 'received' || s === 'requested' ? s : s === 'verified' ? 'verified' : s)
export function compare(doc: DocumentRow, docs: DocumentRow[]) {
 const prior = doc.supersedes ? docs.find(d => d.id === doc.supersedes) : null
 return prior ? { previous: prior.id, identical_bytes: prior.sha256 === doc.sha256, size_change: doc.size - prior.size, effective: [prior.effective_on, doc.effective_on], expires: [prior.expires_on, doc.expires_on] } : null
}
const post = (action: string, body: string, label: string, cls = 'button-secondary') => `<form method="post" action="${action}">${body}<button class="${cls}">${escape(label)}</button></form>`
export async function vendorPage(d: Detail, people: Person[], now: Date, owner: string, issued: { url: string; expires_at: string; emailed: boolean } | null) {
 const v = d.vendor, p = d.profile, id = v.id, base = `/app/vendors/${id}`, st = standing(d.approvals, now)
 const abroad = p && !usRegion(p.region)
 const prerequisites = [
  ...(p?.data_types.includes('PHI') ? ['A signed business associate agreement (45 CFR 164.308(b)(1)) before ePHI reaches this supplier'] : []),
  ...(p?.data_types.includes('personal data') ? ['A data processing agreement covering the personal data it processes'] : []),
  ...(abroad ? [`Regional controls: ${p!.region} is outside the US; confirm residency, transfer terms and local law with counsel`] : []),
 ]
 const profile = slab(`<section aria-labelledby="profile-title"><h2 id="profile-title">Profile</h2>${facts([['Supplier', escape(v.name)], ['Provides', escape(p?.service || '—')], ['Website', p?.website ? `<a href="${escape(p.website)}" rel="noopener noreferrer">${escape(p.website)}</a>` : '—'], ['Criticality', escape(v.criticality)], ['Risk tier', escape(`${p?.risk_tier ?? '—'}${p ? ' · ' + p.tier_basis : ''}`)], ['Data access', escape([...(p?.data_types ?? []), v.data_access].filter(Boolean).join('; ') || '—')], ['Region', escape(p?.region ?? '—')], ['Annual cost', p?.annual_cost_usd == null ? '—' : escape('$' + p.annual_cost_usd.toLocaleString('en-US') + ' USD')], ['Contract renewal', escape(p?.renewal_date ? usDate(p.renewal_date) : '—')], ['Contact', escape(p ? `${p.contact_name} ${p.contact_email}`.trim() || '—' : '—')], ['Business owner', escape((d.owner_name ?? '—') + ownerLeft(d.owner_left_at))], ['Profile revision', String(p?.revision ?? 0)]])}
  <details><summary>Edit profile</summary><form method="post" action="${base}" class="stack"><label>Reason for the change<input name="reason" required maxlength="500"></label><label>Provides<input name="service" maxlength="500" value="${escape(p?.service ?? '')}"></label><label>Website<input name="website" type="url" value="${escape(p?.website ?? '')}"></label><label>Criticality<select name="criticality" aria-label="Criticality">${options([...criticalities], v.criticality)}</select></label><fieldset><legend>Data the supplier can access</legend>${dataTypes.map(t => `<label><input type="checkbox" name="data_types" value="${escape(t)}"${p?.data_types.includes(t) ? ' checked' : ''}> ${escape(t)}</label>`).join(' ')}</fieldset><label>Data access notes<input name="data_access" maxlength="500" value="${escape(v.data_access)}"></label><label>Hosting region<input name="region" value="${escape(p?.region ?? 'US')}"></label><label>Risk tier<select name="risk_tier" aria-label="Risk tier"><option value="">Suggest again</option>${options([...tiers], p?.risk_tier ?? '')}</select></label><label>Annual cost (USD)<input name="annual_cost_usd" inputmode="numeric" value="${p?.annual_cost_usd ?? ''}"></label><label>Contract renewal date<input type="date" name="renewal_date" value="${escape(p?.renewal_date ?? '')}"></label><label>Contact name<input name="contact_name" value="${escape(p?.contact_name ?? '')}"></label><label>Contact email<input type="email" name="contact_email" value="${escape(p?.contact_email ?? '')}"></label><label>Business owner<select name="owner_person_id" aria-label="Business owner">${personOptions(people, v.owner_person_id ?? '', 'No owner yet')}</select></label><button class="button-secondary">Save profile</button></form></details></section>`)
 const prereq = slab(`<section aria-labelledby="prereq-title"><h2 id="prereq-title">Prerequisites and disclosures</h2>${prerequisites.length ? `<ul>${prerequisites.map(x => `<li>${escape(x)} <em>(not verified by Evidence)</em></li>`).join('')}</ul>` : '<p>No agreement prerequisite is recorded for the data this supplier can access.</p>'}<p>You and the supplier decide and sign these agreements; Evidence keeps the signed copies you upload and never signs or certifies for either party. Costs are shown in USD.</p></section>`)
 const status = slab(`<section aria-labelledby="status-title"><h2 id="status-title">Approval and reassessment</h2>${facts([['Approval', stateChip(st.approval)], ['Reassessment', `${stateChip(st.reassessment)} ${escape(st.reassess_by ? 'by ' + usDate(st.reassess_by) : '')}`], ['Condition', escape(st.condition ?? '—')]])}</section>`)
 const need = slab(`<section aria-labelledby="needs-title"><h2 id="needs-title">Diligence checklist</h2>${table(['Item', 'State', 'Detail'], d.needs.map(n => [escape(n.label), stateChip(n.state), escape(n.detail)]), 'Diligence checklist')}</section>`)
 const verifiedDocs = d.documents.filter(x => x.review_state === 'verified')
 const docRows = d.documents.map(x => { const c = compare(x, d.documents); return [escape(kindLabels[x.kind]), `<a href="${base}/documents/${x.id}/download">${escape(x.filename)}</a><br><small>sha256 ${escape(x.sha256.slice(0, 16))}…</small><br><a href="${base}/documents/${x.id}/reviews">Cited document reviews</a>`, escape(x.origin === 'supplier' ? 'Supplier-provided' : 'Owner-uploaded') + `<br><small>${escape(x.provided_by)}</small>`, escape((x.effective_on ? usDate(x.effective_on) : '—') + (x.expires_on ? ' to ' + usDate(x.expires_on) : '')), when(x.added_at), c ? escape(c.identical_bytes ? 'Same bytes as the previous version' : `Replaces ${c.previous.slice(0, 8)}; size ${c.size_change >= 0 ? '+' : ''}${c.size_change} bytes`) : '—', x.review_state === 'received' ? post(`${base}/documents/${x.id}/review`, '<label>Notes<input name="notes" required maxlength="1000"></label><label>Decision<select name="decision" aria-label="Decision"><option value="verified">Verified</option><option value="rejected">Rejected</option></select></label>', 'Record review') : `${stateChip(x.review_state)}<br><small>${escape(x.reviewed_by ?? '')} ${escape(x.review_notes ?? '')}</small>`] })
 const docs = slab(`<section aria-labelledby="docs-title"><h2 id="docs-title">Documents</h2><p class="panel-intro">Originals are kept unchanged; a newer version never replaces the earlier bytes. A document is verified evidence only after you review it.</p>${table(['Kind', 'File', 'Source', 'Effective', 'Received', 'Version', 'Review'], docRows, 'Vendor documents')}<form method="post" action="${base}/documents" enctype="multipart/form-data" class="stack"><h3>Add a signed agreement or report</h3><label>Kind<select name="kind" aria-label="Document kind">${options(Object.entries(kindLabels).filter(([k]) => k !== 'questionnaire'))}</select></label><label>File<input type="file" name="file" required></label><label>Effective date<input type="date" name="effective_on"></label><label>Expires on<input type="date" name="expires_on"></label><button class="button-secondary">Store document</button></form></section>`)
 const reqRows = d.requests.map(r => [escape(r.label), stateChip(requestState(r)), escape(r.due_date ?? '—'), escape(r.kind === 'questionnaire' ? (r.submitted_at ? `Submitted ${r.submitted_at.slice(0, 10)} by ${r.respondent_name}` : '—') : `${r.received_documents} document(s)`), requestState(r) === 'open' ? post(`${base}/requests/${r.id}/close`, '<label>Reason<input name="reason" required maxlength="500"></label>', 'Close request') : escape(r.closed_reason ?? '')])
 const open = d.requests.filter(r => requestState(r) === 'open')
 const issueForm = `<form method="post" action="${base}/requests" class="stack"><h3>Send a supplier request link</h3><fieldset><legend>Request</legend>${['soc2', 'soc1', 'iso27001', 'pentest', 'baa', 'dpa', 'questionnaire'].map(k => `<label><input type="checkbox" name="kinds" value="${k}"${(k === 'baa' && p?.data_types.includes('PHI')) || k === 'soc2' ? ' checked' : ''}> ${escape(kindLabels[k])}</label>`).join(' ')}</fieldset>
  <label>Questionnaire template<select name="template_id" aria-label="Questionnaire template">${options(d.templates.map(t => [t.id, `${t.name} (${t.questions.length} questions)`] as [string, string]), 'caiq-v4')}</select></label>
  ${open.length ? `<fieldset><legend>Also include open requests</legend>${open.map(r => `<label><input type="checkbox" name="request_ids" value="${r.id}"> ${escape(r.label)}</label>`).join(' ')}</fieldset>` : ''}
  <label>Link expires (UTC, at most 90 days)<input type="date" name="expires_at" required></label><label>Requested by<input type="date" name="due_date"></label><label>Supplier contact email<input type="email" name="contact_email" value="${escape(p?.contact_email ?? '')}"></label>
  <label><input type="checkbox" name="send_email" value="yes"> Email the link to this contact now (otherwise you copy it yourself)</label><button class="button-secondary">Create link</button></form>`
 const issuedBox = issued ? `<div class="panel" role="status"><h3>Supplier link created</h3><p>Copy it now; it is shown once and only a digest is kept. It expires ${escape(issued.expires_at)}${issued.emailed ? ' and was emailed to the supplier contact' : ''}.</p><p><code>${escape(issued.url)}</code></p></div>` : ''
 const linkRows = d.links.map(l => [escape(l.contact_email || '—'), escape(l.expires_at), escape(l.created_by), String(l.requests), l.closed_at ? stateChip('closed') : Date.parse(l.expires_at) <= now.getTime() ? stateChip('expired') : stateChip('active'), l.closed_at || Date.parse(l.expires_at) <= now.getTime() ? '' : post(`${base}/links/${l.id}/close`, '', 'Close link')])
 const requests = slab(`<section aria-labelledby="req-title"><h2 id="req-title">Requests and supplier links</h2>${issuedBox}${table(['Request', 'State', 'Requested by', 'Received', ''], reqRows, 'Requests')}${table(['Contact', 'Expires', 'Created by', 'Requests', 'State', ''], linkRows, 'Supplier links')}${issueForm}</section>`)
 const answerBlocks = d.requests.filter(r => r.kind === 'questionnaire' && d.answers[r.id]?.length).map(r => {
  const qs = r.questions_json ? JSON.parse(r.questions_json) as { id: string; text: string }[] : [], latest = new Map(d.answers[r.id].map(a => [a.question_id, a]))
  return `<details><summary>${escape(r.label)}: ${latest.size} of ${qs.length} answered${r.submitted_at ? ', submitted' : ', in progress'} (supplier-asserted, not verified)</summary>${table(['Question', 'Text', 'Answer', 'Comment'], qs.filter(q => latest.has(q.id)).map(q => [escape(q.id), escape(q.text), escape(latest.get(q.id)!.answer), escape(latest.get(q.id)!.comment)]), 'Answers')}<p>Quote an answer in a finding as <code>${r.id}:QUESTION-ID</code>.</p>${r.submitted_at?post(`${base}/requests/${r.id}/reviews`,'','Prepare cited questionnaire review'):'<p>Submit all answers before preparing a cited review.</p>'}</details>`
 }).join('')
 const answers = slab(`<section aria-labelledby="ans-title"><h2 id="ans-title">Questionnaire answers</h2>${answerBlocks || '<p>No questionnaire answers have been received.</p>'}</section>`)
 const findingRows = d.findings.map(f => [escape(f.severity ?? ''), escape(f.title ?? ''), escape(`${f.source_kind}${f.source_ref ? ': ' + f.source_ref : ''}`), stateChip(f.state ?? ''), f.state === 'open' ? `<details><summary>Decide</summary>${post(`${base}/findings/${f.id}/decision`, '<input type="hidden" name="decision" value="resolved"><label>Resolution<input name="reason" required maxlength="1000"></label>', 'Mark resolved')}${post(`${base}/findings/${f.id}/decision`, `<input type="hidden" name="decision" value="accepted"><label>Exception reason<input name="reason" required maxlength="1000"></label><label>Named approver<select name="approver_person_id" aria-label="Named approver">${personOptions(people)}</select></label>`, 'Accept as exception')}</details>` : escape(`${f.decision_reason ?? ''}${f.approver_name ? ' · approver ' + f.approver_name : ''}`)])
 const findings = slab(`<section aria-labelledby="find-title"><h2 id="find-title">Findings</h2>${table(['Severity', 'Finding', 'Source', 'State', 'Decision'], findingRows, 'Findings')}<form method="post" action="${base}/findings" class="stack"><h3>Record a finding</h3><label>Title<input name="title" required maxlength="300"></label><label>Detail<input name="detail" maxlength="2000"></label><label>Severity<select name="severity" aria-label="Severity">${options(['low', 'medium', 'high', 'critical'], 'medium')}</select></label><label>Source<select name="source_kind" aria-label="Source"><option value="manual">Manual observation</option><option value="document">A vendor document</option><option value="answer">A questionnaire answer</option></select></label><label>Document id or requestId:questionId<input name="source_ref" maxlength="200" list="docs-list"></label><datalist id="docs-list">${d.documents.map(x => `<option value="${x.id}">${escape(x.filename)}</option>`).join('')}</datalist><button class="button-secondary">Record finding</button></form></section>`)
 const approvalRows = d.approvals.map(a => [escape(a.decision), when(a.decided_at), escape(`${a.decided_by}${a.approver_name ? ' · approver ' + a.approver_name : ''}`), escape(a.rationale), escape(a.conditions ? `${a.conditions} (expires ${a.condition_expires_on})${a.condition_closed_at ? ', met ' + a.condition_closed_at.slice(0, 10) : ''}` : '—'), escape((JSON.parse(a.exceptions_json) as string[]).join('; ') || '—'), escape(a.reassess_by), a.decision === 'conditional' && !a.condition_closed_at ? post(`${base}/approvals/${a.id}/condition`, '<label>How it was met<input name="note" required maxlength="1000"></label>', 'Record condition met') : ''])
 const approval = slab(`<section aria-labelledby="appr-title"><h2 id="appr-title">Approval decisions</h2>${table(['Decision', 'When', 'Decided by', 'Rationale', 'Condition', 'Exceptions', 'Reassess by', ''], approvalRows, 'Approvals')}<form method="post" action="${base}/approvals" class="stack"><h3>Record a decision</h3><label>Decision<select name="decision" aria-label="Decision">${options([['approved', 'Approve'], ['conditional', 'Approve with a condition'], ['declined', 'Decline']])}</select></label><label>Rationale<input name="rationale" required maxlength="2000"></label><label>Condition (conditional approval)<input name="conditions" maxlength="1000"></label><label>Condition expires on<input type="date" name="condition_expires_on"></label><label>Named approver (required for exceptions)<select name="approver_person_id" aria-label="Named approver">${personOptions(people)}</select></label><label>Reassess by (blank: ${p?.risk_tier === 'high' ? '6' : '12'} months or renewal)<input type="date" name="reassess_by"></label><button>Record decision</button></form></section>`)
 const assertionRows = d.assertions.map(a => [escape(a.claim ?? ''), a.source_url ? `<a href="${escape(a.source_url)}" rel="noopener noreferrer">${escape(a.source_url)}</a>` : '—', a.verified_document_id ? `${stateChip('verified')} by document ${escape(a.verified_document_id.slice(0, 8))}` : stateChip('unknown') + ' supplier claim, not verified', a.verified_document_id ? '' : verifiedDocs.length ? post(`${base}/assertions/${a.id}/verify`, `<label>Verifying document<select name="document_id" aria-label="Verifying document">${options(verifiedDocs.map(x => [x.id, x.filename] as [string, string]))}</select></label>`, 'Verify with document') : 'Verify a document first'])
 const assertions = slab(`<section aria-labelledby="assert-title"><h2 id="assert-title">Supplier claims (not verified)</h2><p class="panel-intro">Marketing and trust-page statements stay here, apart from verified evidence, until a document you verified supports them.</p>${table(['Claim', 'Source', 'State', ''], assertionRows, 'Claims')}<form method="post" action="${base}/assertions" class="stack"><label>Claim<input name="claim" required maxlength="500"></label><label>Source (https)<input name="source_url" type="url" maxlength="300"></label><button class="button-secondary">Record claim</button></form></section>`)
 const subs = slab(`<section aria-labelledby="sub-title"><h2 id="sub-title">Subprocessors</h2>${table(['Subprocessor', 'Purpose', 'Region', 'State', ''], d.subprocessors.map(s => [escape(s.name ?? ''), escape(s.purpose ?? ''), escape(s.region ?? ''), s.removed_at ? escape('Removed ' + s.removed_at.slice(0, 10)) : stateChip('active'), s.removed_at ? '' : post(`${base}/subprocessors/${s.id}/remove`, '<label>Reason<input name="reason" required maxlength="500"></label>', 'Remove')]), 'Subprocessors')}<form method="post" action="${base}/subprocessors" class="stack"><label>Name<input name="name" required maxlength="200"></label><label>Purpose<input name="purpose" maxlength="300"></label><label>Region<input name="region" maxlength="100"></label><button class="button-secondary">Add subprocessor</button></form></section>`)
 const log = slab(`<section aria-labelledby="log-title"><h2 id="log-title">Reminders and link activity</h2>${table(['Reminder', 'Cycle', 'Sent to', 'State', 'When'], d.reminders.map(r => [escape(r.kind), escape(r.cycle_key), escape(r.recipient), stateChip(r.state), when(r.created_at)]), 'Reminders')}${table(['Link activity', 'Outcome', 'When'], d.events.map(e => [escape(e.action), stateChip(e.outcome === 'allowed' ? 'active' : 'unknown') + ' ' + escape(e.outcome), when(e.at)]), 'Link activity')}</section>`)
 return page(v.name, `<p class="page-intro"><a href="/app/vendors">All vendors</a></p><div class="app-columns">${profile}${status}</div><div class="app-columns">${prereq}${need}</div>${docs}<p><a href="/app/vendors/obligations">CUEC readiness obligations</a></p><form method="post" action="${base}/review-settings"><label>Bridge window (calendar months)<input type="number" name="bridge_months" min="1" max="24" required></label><button>Set bridge window</button></form>${requests}${answers}${findings}${approval}<div class="app-columns">${assertions}${subs}</div>${log}`, 200, { owner, active: 'vendors' })
}
